"use strict";(globalThis.webpackChunkmy_website||=[]).push([[52433],{82012(e){e.exports=JSON.parse('{"slug":"proof-of-stake","title":"Proof of Stake","short":"A consensus mechanism where validators are selected to create blocks based on the amount of cryptocurrency they hold and stake (commit) to the network.","category":"consensus","aliases":[],"mentalModel":"Trust earned by skin in the game: your influence in the network scales with how much ada you hold and stake, not with how much computing power you can throw at it.","related":["ouroboros","proof-of-work","stake-pool"],"sources":[],"link":null,"level":"beginner","body":"A consensus mechanism where validators are selected to create blocks based on the amount of cryptocurrency they hold and stake (commit) to the network. Cardano uses proof of stake via [Ouroboros](/ouroboros/), where delegated ada stays liquid in your wallet and is never locked or slashed."}')}}]);